function getProcessHistoryActor() {
  try {
    const settings = loadProfileSettings();
    return String(settings?.profileName || "CEC").trim() || "CEC";
  } catch {
    return "CEC";
  }
}

function recordProcessHistory(processo, tipo, titulo, detalhes = "", extras = {}) {
  if (!processo) return;

  ensureProcessRoutingData(processo);

  const now = new Date();
  const data = extras.data || isoDate(now);
  const hora = extras.hora || now.toTimeString().slice(0, 5);

  processo.historicoAcoes.push({
    id: createId("hist"),
    refId: extras.refId || "",
    tipo: tipo || "Registro",
    titulo: titulo || tipo || "Registro",
    detalhes: String(detalhes || "").trim(),
    usuario: extras.usuario || getProcessHistoryActor(),
    data,
    hora,
    criadoEm: extras.criadoEm || `${data}T${hora}:00`
  });
}

function normalizeHistoryCompareValue(value) {
  if (value === null || value === undefined || value === "") return "—";
  return String(value).trim() || "—";
}

function describeProcessChanges(before = {}, after = {}) {
  const fields = [...PROCESS_FIELDS, "setorAtual"];
  const changes = [];

  fields.forEach(field => {
    const oldValue = normalizeHistoryCompareValue(before[field]);
    const newValue = normalizeHistoryCompareValue(after[field]);

    if (oldValue === newValue) return;

    const label = PROCESS_HISTORY_FIELD_LABELS[field] || field;
    changes.push(`${label}: ${oldValue} → ${newValue}`);
  });

  return changes;
}

function historySortValue(item = {}) {
  const iso = item.criadoEm
    || (item.data ? `${item.data}T${item.hora || "00:00"}:00` : "");

  const time = Date.parse(iso);
  return Number.isFinite(time) ? time : 0;
}

function formatHistoryDateTime(item = {}) {
  if (!item.data) return "Data não informada";

  const [year, month, day] = String(item.data).split("-");
  const date = year && month && day
    ? `${day}/${month}/${year}`
    : item.data;

  return item.hora ? `${date} às ${item.hora}` : date;
}

function renderProcessHistory(processo) {
  if (!processHistoryList || !processo) return;

  ensureProcessRoutingData(processo);

  if (processHistoryTitle) {
    processHistoryTitle.textContent = `Histórico — ${processo.numero || "Processo"}`;
  }

  if (processHistorySector) {
    processHistorySector.textContent = processo.setorAtual || "CEC";
  }

  const items = [...processo.historicoAcoes]
    .sort((a, b) => historySortValue(b) - historySortValue(a));

  if (!items.length) {
    processHistoryList.innerHTML = `
      <div class="process-history-empty">
        Ainda não há registros anteriores neste histórico.<br>
        As próximas ações realizadas no processo serão registradas automaticamente.
      </div>
    `;
    return;
  }

  processHistoryList.innerHTML = items.map(item => `
    <article class="process-history-item" data-history-type="${escapeHtml(item.tipo || "Registro")}">
      <div class="process-history-item-head">
        <strong>${escapeHtml(item.titulo || item.tipo || "Registro")}</strong>
        <span class="process-history-item-time">${escapeHtml(formatHistoryDateTime(item))}</span>
      </div>

      ${item.detalhes
        ? `<p>${escapeHtml(item.detalhes)}</p>`
        : ""}

      <div class="process-history-user">
        Registrado por: ${escapeHtml(item.usuario || "CEC")}
      </div>
    </article>
  `).join("");
}

function openProcessHistory() {
  const processId = editProcessForm?.elements?.id?.value;
  const processo = processos.find(item => item.id === processId);

  if (!processo) {
    showToast("Processo não encontrado.");
    return;
  }

  renderProcessHistory(processo);
  processHistoryModal?.classList.add("open");
  processHistoryModal?.setAttribute("aria-hidden", "false");
}

function closeProcessHistory() {
  processHistoryModal?.classList.remove("open");
  processHistoryModal?.setAttribute("aria-hidden", "true");
}

function saveProcessos() {
  // Registra primeiro a alteração no processo compartilhado. Sem esta etapa,
  // o estado antigo (recebido=false) reaparece após atualizar a página.
  window.SEADSync?.save();
  localStorage.setItem(PROCESS_STORAGE, JSON.stringify(processos));
}

function saveAgenda() {
  localStorage.setItem(AGENDA_STORAGE, JSON.stringify(agenda));
}

function createId(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function escapeHtml(value = "") {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function formatDate(date) {
  if (!date) return "—";
  return new Intl.DateTimeFormat("pt-BR").format(new Date(`${date}T12:00:00`));
}

function formatDateLong(date) {
  return new Intl.DateTimeFormat("pt-BR", {
    weekday: "long",
    day: "2-digit",
    month: "long",
    year: "numeric"
  }).format(date);
}

function isoDate(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function sameDay(a, b) {
  return a.getFullYear() === b.getFullYear()
    && a.getMonth() === b.getMonth()
    && a.getDate() === b.getDate();
}

function textEqualsCI(a, b) {
  return String(a || "").trim().toLocaleUpperCase("pt-BR")
    === String(b || "").trim().toLocaleUpperCase("pt-BR");
}

function statusClass(status) {
  const key = String(status || "").trim().toLocaleUpperCase("pt-BR");
  const map = {
    "AGUARDANDO ABERTURA": "aguardando",
    "ABERTO": "aberto",
    "AGUARDANDO REABERTURA": "reabertura",
    "FINALIZADO": "finalizado",
    "EM ANDAMENTO": "andamento",
    "PRÓXIMO DO PRAZO": "proximo",
    "VENCIDO": "vencido",
    "CONCLUÍDO": "concluido"
  };
  return map[key] || "andamento";
}

function showToast(message) {
  if (!toast) return;
  const now = new Date();
  const timeLabel = now.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
  toast.innerHTML = `
    <div class="toast-card">
      <div class="toast-header">
        <div class="toast-header-left">
          <span class="toast-app-icon">🔔</span>
          <div class="toast-title-wrap">
            <strong class="toast-title">CEC</strong>
            <span class="toast-subtitle">Novo recebimento</span>
          </div>
        </div>
        <button type="button" class="toast-close-btn" aria-label="Fechar notificação">×</button>
      </div>
      <div class="toast-body">${escapeHtml(message || "Novo processo recebido.")}</div>
      <div class="toast-time">${timeLabel}</div>
      <div class="toast-actions">
        <button type="button" class="toast-dismiss-btn">Dispensar</button>
      </div>
    </div>
  `;
  toast.classList.add("show");
  const hideToast = () => toast.classList.remove("show");
  const closeBtn = toast.querySelector(".toast-close-btn");
  const dismissBtn = toast.querySelector(".toast-dismiss-btn");
  closeBtn?.addEventListener("click", hideToast, { once: true });
  dismissBtn?.addEventListener("click", hideToast, { once: true });
  window.clearTimeout(showToast.timer);
  showToast.timer = window.setTimeout(hideToast, 5200);
}

function setActiveNav(section) {
  document.querySelectorAll(".nav-tab").forEach(button => {
    button.classList.toggle("active", button.dataset.section === section);
  });
}

function showSection(section) {
  currentSection = section;

  document.querySelectorAll(".app-section").forEach(sectionEl => {
    sectionEl.classList.remove("active");
  });

  const target = document.querySelector(`#section-${section}`);
  if (target) target.classList.add("active");

  if (section !== "processo-detalhe") {
    setActiveNav(section);
  }

  const pageConfig = {
    dashboard: ["Visão geral", "Acompanhe o que precisa de atenção hoje."],
    recebimento: ["Recebimento", "Confirme os processos encaminhados para a CEC."],
    processos: ["Processos", "Consulte e acompanhe os processos recebidos pela CEC."],
    "processo-detalhe": ["Processo", "Consulta e edição das informações do processo."],
    agenda: ["Agenda", "Calendário de processos por dia, mês e ano."],
    prazos: ["Prazos", "Acompanhamento dos vencimentos dos processos."],
    relatorios: ["Relatórios", "Consulta e consolidação das informações da CEC."]
  };

  const [title, subtitle] = pageConfig[section] || pageConfig.dashboard;
  pageTitle.textContent = title;
  pageSubtitle.textContent = subtitle;

  searchBox.style.display = section === "dashboard" ? "" : "none";

  if (section === "dashboard") renderDashboard();
  if (section === "recebimento") renderRecebimento();
  if (section === "processos") renderProcessos();
  if (section === "agenda") renderCalendar();
  if (section === "prazos") renderDeadlines();
  if (section === "relatorios") renderReports();

  window.scrollTo({ top: 0, behavior: "smooth" });
}



function currencyValueToNumber(value) {
  if (value === null || value === undefined || value === "") return 0;

  const text = String(value)
    .replace(/R\$/gi, "")
    .replace(/\s/g, "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.-]/g, "");

  const number = Number(text);
  return Number.isFinite(number) ? number : 0;
}

function formatReportCurrency(value) {
  return new Intl.NumberFormat("pt-BR", {
    style: "currency",
    currency: "BRL"
  }).format(Number(value) || 0);
}

function reportProcessYear(processo) {
  if (processo.anoLicitacao) return String(processo.anoLicitacao);

  const candidates = [
    processo.dataAbertura,
    processo.dataEntradaSelic,
    processo.dataInicial,
    processo.dataFinal
  ];

  for (const value of candidates) {
    const match = String(value || "").match(/^(20\d{2})-/);
    if (match) return match[1];
  }

  const licitacaoMatch = String(processo.numeroLicitacao || "").match(/\/(20\d{2})$/);
  return licitacaoMatch ? licitacaoMatch[1] : "";
}

// Agrupa grafias equivalentes sem fundir modalidades distintas, como as com SRP.
function reportModalidadeLabel(value) {
  const text = String(value ?? "").normalize("NFKC").trim().replace(/\s+/g, " ");
  return text ? text.toLocaleUpperCase("pt-BR") : "Sem modalidade";
}

function populateReportSelect(select, values, allLabel) {
  if (!select) return;

  const current = select.value;
  const unique = [];
  const seen = new Set();

  values
    .map(value => String(value || "").trim())
    .filter(Boolean)
    .forEach(value => {
      const key = value.toLocaleUpperCase("pt-BR");
      if (seen.has(key)) return;
      seen.add(key);
      unique.push(value);
    });

  unique.sort((a, b) => a.localeCompare(b, "pt-BR", { numeric: true, sensitivity: "base" }));

  select.innerHTML = [
    `<option value="">${escapeHtml(allLabel)}</option>`,
    ...unique.map(value => `<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`)
  ].join("");

  if (current) {
    const match = unique.find(value => textEqualsCI(value, current));
    if (match) select.value = match;
  }
}

// Mesma base da Visão Geral: processos recebidos (incluindo já enviados).
// Itens ainda pendentes de Recebimento permanecem fora das estatísticas.
function getReportSourceProcesses() {
  return processos.filter(isCecOperationalProcess);
}

function populateReportFilters() {
  const reportSources = getReportSourceProcesses();
  const settings = typeof loadProfileSettings === "function"
    ? loadProfileSettings()
    : { orgaos: [], modalidades: [], statuses: [] };

  populateReportSelect(
    reportYearFilter,
    reportSources.map(reportProcessYear),
    "Todos"
  );

  populateReportSelect(
    reportOrgaoFilter,
    [...(settings.orgaos || []), ...reportSources.map(p => p.orgao)],
    "Todos"
  );

  populateReportSelect(
    reportModalidadeFilter,
    [...(settings.modalidades || []), ...reportSources.map(p => p.modalidade)]
      .filter(Boolean).map(reportModalidadeLabel),
    "Todas"
  );

  populateReportSelect(
    reportStatusFilter,
    [...(settings.cecStatuses || []), ...reportSources.map(p => p.statusCec)],
    "Todos"
  );

  populateReportSelect(
    reportPregoeiroFilter,
    reportSources.map(p => p.pregoeiroCec),
    "Todos"
  );

  populateReportSelect(
    reportSetorFilter,
    ["DIVACP", "DIVCON", "CEC", "CEC", "DIPREG", ...reportSources.map(p => p.setorAtual || p.setorResponsavel)],
    "Todos"
  );
}

function getFilteredReportProcesses({ ignoreChartSelection = false } = {}) {
  const year = reportYearFilter?.value || "";
  const orgao = reportOrgaoFilter?.value || "";
  const modalidade = reportModalidadeFilter?.value || "";
  const status = reportStatusFilter?.value || "";
  const pregoeiro = reportPregoeiroFilter?.value || "";
  const setor = reportSetorFilter?.value || "";
  const term = String(reportSearchInput?.value || "").trim().toLocaleLowerCase("pt-BR");

  return getReportSourceProcesses().filter(p => {
    if (!ignoreChartSelection && !reportChartMatchesSelected(p)) return false;
    if (year && reportProcessYear(p) !== year) return false;
    if (orgao && !textEqualsCI(p.orgao, orgao)) return false;
    if (modalidade && !textEqualsCI(p.modalidade, modalidade)) return false;
    if (status && !textEqualsCI(p.statusCec, status)) return false;
    if (pregoeiro && (p.pregoeiroCec || "") !== pregoeiro) return false;
    if (setor && (p.setorAtual || p.setorResponsavel || "CEC") !== setor) return false;

    if (!term) return true;

    return [
      p.numero,
      p.numeroLicitacao,
      p.orgao,
      p.modalidade,
      p.status,
      p.responsavel,
      p.setorAtual || p.setorResponsavel,
      p.objeto,
      p.fonte
    ]
      .some(value =>
        String(value || "")
          .toLocaleLowerCase("pt-BR")
          .includes(term)
      );
  });
}


