function reportChartColors(count, offset = 0) {
  const palette = [
    "#2869d8", "#13a589", "#f29d35", "#7456d8",
    "#de5d72", "#2f93b5", "#9aa83b", "#ba6e3a",
    "#5d82bd", "#8c69a8", "#4a9f6d", "#cb7f9d",
    "#e05e3f", "#4375c4", "#2f9e76", "#a35bc1"
  ];

  return Array.from(
    { length: count },
    (_, index) => palette[(index + offset) % palette.length]
  );
}

function selicReportGroupKey(value) {
  return String(value ?? "").trim().normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ").toLocaleUpperCase("pt-BR");
}
function selicReportDisplayLabel(value) {
  const v = String(value ?? "").trim().replace(/\s+/g, " ");
  return v ? v.toLocaleUpperCase("pt-BR") : "SEM INFORMAÇÃO";
}
function buildReportChartData(items, groupKey = "status") {
  const metricKey = reportChartMetric?.value || "count";
  const group = REPORT_CHART_GROUPS[groupKey] || REPORT_CHART_GROUPS.status;
  const metric = REPORT_CHART_METRICS[metricKey] || REPORT_CHART_METRICS.count;
  const totals = new Map();

  items.forEach(processo => {
    const label = String(group.getter(processo) || "Sem informação").trim() || "Sem informação";
    const value = Number(metric.value(processo)) || 0;
    const key = selicReportGroupKey(label);
    const prior = totals.get(key);
    totals.set(key, { label: selicReportDisplayLabel(label), value: (prior?.value || 0) + value });
  });

  let entries = [...totals.values()].map(({ label, value }) => [label, value]);

  entries.sort((a, b) => {
    if (groupKey === "ano") {
      return a[0].localeCompare(b[0], "pt-BR", { numeric: true, sensitivity: "base" });
    }

    return b[1] - a[1];
  });

  return {
    groupKey,
    metricKey,
    group,
    metric,
    labels: entries.map(([label]) => label),
    values: entries.map(([, value]) => value)
  };
}


