function renderDeadlines() {
  updateStats();

  const filter = deadlineFilter.value;
  let items = [...processos].sort((a, b) => (a.dataFinal || "9999-12-31").localeCompare(b.dataFinal || "9999-12-31"));

  const today = isoDate(new Date());
  if (filter === "proximos") items = items.filter(p => !textEqualsCI(p.status, "FINALIZADO") && p.dataFinal && p.dataFinal >= today);
  if (filter === "vencidos") items = items.filter(p => !textEqualsCI(p.status, "FINALIZADO") && p.dataFinal && p.dataFinal < today);
  if (filter === "concluidos") items = items.filter(p => textEqualsCI(p.status, "FINALIZADO"));

  deadlineList.innerHTML = items.length
    ? items.map(p => `
      <article class="deadline-item">
        <div>
          <button class="process-link" data-process-id="${escapeHtml(p.id)}">${escapeHtml(p.numero)}</button>
          <div class="deadline-owner">${escapeHtml(p.responsavel)}</div>
        </div>
        <div class="deadline-subject">${escapeHtml(p.objeto)}</div>
        <div class="deadline-date">${formatDate(p.dataFinal)}</div>
        <div><span class="status ${statusClass(p.status)}">${escapeHtml(p.status)}</span></div>
      </article>
    `).join("")
    : '<div class="empty-calendar">Nenhum prazo encontrado para o filtro selecionado.</div>';

  bindProcessLinks();
}

