    objeto: (data.get("objeto")?.trim() || "").toLocaleUpperCase("pt-BR"),
    modalidade: String(data.get("modalidade") || "").trim().toLocaleUpperCase("pt-BR"),
    numeroLicitacao: data.get("numeroLicitacao")?.trim() || "",
    fonte: (data.get("fonte")?.trim() || "").toLocaleUpperCase("pt-BR"),
