const PROFILE_SETTINGS_STORAGE = "cec_lab_profile_settings_v1";
const CEC_V18_FONT_MIGRATION = "cec_lab_v18_font_standardized_v1";


const DEFAULT_PROFILE_FONT = "Inter";

const DEFAULT_PROFILE_FONT_SIZE = 12;

function normalizeProfileFontSize(value) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return DEFAULT_PROFILE_FONT_SIZE;
  return Math.max(10, Math.min(18, Math.round(parsed)));
}

function applyProfileFontSize(value = DEFAULT_PROFILE_FONT_SIZE) {
  const size = normalizeProfileFontSize(value);
  const isDefault = size === DEFAULT_PROFILE_FONT_SIZE;

  document.documentElement.dataset.cecFontCustom = isDefault ? "0" : "1";
  document.documentElement.style.setProperty("--app-font-size", `${size}px`);
  document.documentElement.style.setProperty("--app-font-scale", String(size / DEFAULT_PROFILE_FONT_SIZE));

  const range = document.querySelector("#profileFontSizeRange");
  const output = document.querySelector("#profileFontSizeValue");
  if (range) range.value = String(size);
  if (output) output.textContent = isDefault ? "PADRÃO DIVACP" : `${size} px`;

  if (window.Chart?.defaults?.font) {
    window.Chart.defaults.font.size = isDefault ? 12 : Math.max(9, Math.round(size * 0.92));
  }

  return size;
}


const PROFILE_FONT_OPTIONS = {
  "Inter": '"Inter", sans-serif',
  "Aptos": 'Aptos, Calibri, "Segoe UI", Arial, sans-serif',
  "Calibri": 'Calibri, "Segoe UI", Arial, sans-serif',
  "Arial": 'Arial, Helvetica, sans-serif',
  "Cambria": 'Cambria, Georgia, "Times New Roman", serif',
  "Times New Roman": '"Times New Roman", Times, serif',
  "Georgia": 'Georgia, "Times New Roman", serif',
  "Garamond": 'Garamond, Georgia, "Times New Roman", serif',
  "Century Gothic": '"Century Gothic", CenturyGothic, AppleGothic, sans-serif',
  "Segoe UI": '"Segoe UI", Arial, sans-serif',
  "Verdana": 'Verdana, Geneva, sans-serif',
  "Tahoma": 'Tahoma, Geneva, sans-serif',
  "Trebuchet MS": '"Trebuchet MS", Arial, sans-serif',
  "Courier New": '"Courier New", Courier, monospace'
};

function normalizeProfileFont(value) {
  const name = String(value || "").trim();
  return Object.prototype.hasOwnProperty.call(PROFILE_FONT_OPTIONS, name)
    ? name
    : DEFAULT_PROFILE_FONT;
}

function applyProfileFont(fontName = DEFAULT_PROFILE_FONT) {
  const normalized = normalizeProfileFont(fontName);
  const family = PROFILE_FONT_OPTIONS[normalized];

  document.documentElement.style.setProperty("--app-font-family", family);

  if (window.Chart?.defaults?.font) {
    window.Chart.defaults.font.family = family;
  }

  return normalized;
}

function setProfileFontInput(fontName) {
  const select = document.querySelector("#profileFontSelect");
  if (!select) return;
  select.value = normalizeProfileFont(fontName);
}

const DEFAULT_THEME_COLORS = {
  primary: "#1f6feb",
  sidebar: "#132941",
  accent: "#087f79",
  background: "#f3f6fa",
  buttons: "#1f6feb",
  text: "#172033",
  filters: "#ffffff",
  table: "#ffffff"
};

function validHexColor(value, fallback) {
  const text = String(value || "").trim();
  return /^#[0-9a-f]{6}$/i.test(text) ? text.toLowerCase() : fallback;
}

function normalizeThemeColors(colors = {}) {
  return {
    primary: validHexColor(colors.primary, DEFAULT_THEME_COLORS.primary),
    sidebar: validHexColor(colors.sidebar, DEFAULT_THEME_COLORS.sidebar),
    accent: validHexColor(colors.accent, DEFAULT_THEME_COLORS.accent),
    background: validHexColor(colors.background, DEFAULT_THEME_COLORS.background),
    buttons: validHexColor(colors.buttons, DEFAULT_THEME_COLORS.buttons),
    text: validHexColor(colors.text, DEFAULT_THEME_COLORS.text),
    filters: validHexColor(colors.filters, DEFAULT_THEME_COLORS.filters),
    table: validHexColor(colors.table, DEFAULT_THEME_COLORS.table)
  };
}

function hexToRgba(hex, alpha = 1) {
  const safe = validHexColor(hex, "#000000").slice(1);
  const r = parseInt(safe.slice(0, 2), 16);
  const g = parseInt(safe.slice(2, 4), 16);
  const b = parseInt(safe.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function shadeHexColor(hex, factor = .84) {
  const safe = validHexColor(hex, "#1f6feb").slice(1);
  const parts = [0, 2, 4].map(index =>
    Math.max(0, Math.min(255, Math.round(parseInt(safe.slice(index, index + 2), 16) * factor)))
  );
  return `#${parts.map(value => value.toString(16).padStart(2, "0")).join("")}`;
}

function readableTextOnColor(hex) {
  const safe = validHexColor(hex, "#ffffff").slice(1);
  const r = parseInt(safe.slice(0, 2), 16);
  const g = parseInt(safe.slice(2, 4), 16);
  const b = parseInt(safe.slice(4, 6), 16);
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance > .62 ? "#172033" : "#ffffff";
}

function applyThemeColors(colors = DEFAULT_THEME_COLORS) {
  const theme = normalizeThemeColors(colors);
  const root = document.documentElement;

  root.style.setProperty("--blue", theme.primary);
  root.style.setProperty("--blue-dark", shadeHexColor(theme.primary, .84));
  root.style.setProperty("--blue-soft", hexToRgba(theme.primary, .10));
  root.style.setProperty("--layout-navy", theme.sidebar);
  root.style.setProperty("--layout-navy-2", theme.sidebar);
  root.style.setProperty("--layout-teal", theme.accent);
  root.style.setProperty("--layout-teal-soft", hexToRgba(theme.accent, .10));
  root.style.setProperty("--layout-bg", theme.background);
  root.style.setProperty("--bg", theme.background);

  root.style.setProperty("--text", theme.text);
  root.style.setProperty("--theme-text", theme.text);
  root.style.setProperty("--theme-button", theme.buttons);
  root.style.setProperty("--theme-button-hover", shadeHexColor(theme.buttons, .84));
  root.style.setProperty("--theme-button-text", readableTextOnColor(theme.buttons));
  root.style.setProperty("--theme-filter-bg", theme.filters);
  root.style.setProperty("--theme-filter-text", readableTextOnColor(theme.filters));
  root.style.setProperty("--theme-filter-border", hexToRgba(theme.text, .14));
  root.style.setProperty("--theme-table-bg", theme.table);
  root.style.setProperty("--theme-table-text", readableTextOnColor(theme.table));
  root.style.setProperty("--theme-table-border", hexToRgba(theme.text, .12));
}

function setThemeInputs(colors) {
  const theme = normalizeThemeColors(colors);
  const ids = {
    themePrimaryColor: theme.primary,
    themeSidebarColor: theme.sidebar,
    themeAccentColor: theme.accent,
    themeBackgroundColor: theme.background,
    themeButtonColor: theme.buttons,
    themeTextColor: theme.text,
    themeFilterColor: theme.filters,
    themeTableColor: theme.table
  };

  Object.entries(ids).forEach(([id, value]) => {
    const input = document.getElementById(id);
    if (input) input.value = value;
  });
}

function resizeProfileImageFile(file, maxSize = 256) {
  return new Promise((resolve, reject) => {
    if (!file || !String(file.type || "").startsWith("image/")) {
      reject(new Error("Arquivo de imagem inválido."));
      return;
    }

    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Não foi possível ler a imagem."));
    reader.onload = () => {
      const image = new Image();
      image.onerror = () => reject(new Error("Não foi possível abrir a imagem."));
      image.onload = () => {
        const scale = Math.min(1, maxSize / Math.max(image.width, image.height));
        const width = Math.max(1, Math.round(image.width * scale));
        const height = Math.max(1, Math.round(image.height * scale));
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(image, 0, 0, width, height);
        resolve(canvas.toDataURL("image/webp", .88));
      };
      image.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}


function initializeHoverGifs() {
  document.querySelectorAll(".hover-gif").forEach(img => {
    if (img.dataset.hoverGifInitialized === "1") return;

    const trigger = img.closest(".gif-trigger");
    if (!trigger) return;
    img.dataset.hoverGifInitialized = "1";

    const staticSrc = img.dataset.static;
    const animatedSrc = img.dataset.animated;
    if (!staticSrc || !animatedSrc) return;

    const play = () => {
      if (img.dataset.customAvatar === "1") return;
      img.src = `${animatedSrc}?v=${Date.now()}`;
    };

    const stop = () => {
      if (img.dataset.customAvatar === "1") return;
      img.src = staticSrc;
    };

    trigger.addEventListener("mouseenter", play);
    trigger.addEventListener("mouseleave", stop);
    trigger.addEventListener("focusin", play);
    trigger.addEventListener("focusout", stop);
  });
}


