function initializeSidebarNavigation() {
  const sidebar = document.querySelector("#sidebarShell");
  const toggle = document.querySelector("#sidebarToggle");
  const overlay = document.querySelector("#sidebarOverlay");

  if (!sidebar || !toggle || !overlay) return;

  const isMobile = () => window.innerWidth <= 1000;
  const isPersistentlyCollapsed = () =>
    localStorage.getItem("cec_lab_sidebar_collapsed") === "1";

  const closeMobile = () => {
    sidebar.classList.remove("open");
    overlay.classList.remove("open");
  };

  const openMobile = () => {
    sidebar.classList.add("open");
    overlay.classList.add("open");
  };

  const closeDesktopCollapse = () => {
    document.body.classList.remove("sidebar-collapsed");
    sidebar.classList.remove("hover-expanded");
    localStorage.setItem("cec_lab_sidebar_collapsed", "0");
  };

  const openDesktopCollapse = () => {
    document.body.classList.add("sidebar-collapsed");
    sidebar.classList.remove("hover-expanded");
    localStorage.setItem("cec_lab_sidebar_collapsed", "1");
  };

  const applyStoredState = () => {
    sidebar.classList.remove("hover-expanded");

    if (isMobile()) {
      closeMobile();
      document.body.classList.remove("sidebar-collapsed");
      return;
    }

    document.body.classList.toggle(
      "sidebar-collapsed",
      isPersistentlyCollapsed()
    );
  };

  toggle.addEventListener("click", () => {
    if (isMobile()) {
      sidebar.classList.contains("open") ? closeMobile() : openMobile();
      return;
    }

    document.body.classList.contains("sidebar-collapsed")
      ? closeDesktopCollapse()
      : openDesktopCollapse();
  });

  // No desktop, o menu recolhido permanece estreito. O nome de cada função
  // aparece apenas em um flyout lateral ao passar o mouse sobre o ícone.
  sidebar.addEventListener("mouseenter", () => {
    if (!isMobile()) sidebar.classList.remove("hover-expanded");
  });

  sidebar.addEventListener("mouseleave", () => {
    if (!isMobile()) sidebar.classList.remove("hover-expanded");
  });

  overlay.addEventListener("click", closeMobile);

  sidebar.querySelectorAll(".nav-tab").forEach(button => {
    button.addEventListener("click", () => {
      if (isMobile()) closeMobile();
    });
  });

  window.addEventListener("resize", applyStoredState);

  applyStoredState();
}

