const selectedProcessIds = new Set();
let selectedIdsForSending = [];
const dashboardSearchField = document.getElementById("dashboardSearch");
const bulkSendSummary = document.getElementById("sendBulkProcessSummary");
const sendSingleField = document.getElementById("sendSingleProcessField");

function getEligibleSelectedProcessIds() {
  return processos.filter(p => selectedProcessIds.has(String(p.id)) && isProcessInCurrentSector(p))
    .map(p => String(p.id));
}

function updateBatchSelectionControls() {
  for (const checkbox of document.querySelectorAll(".bulk-row-checkbox")) {
    checkbox.checked = selectedProcessIds.has(String(checkbox.value)) && !checkbox.disabled;
  }
  for (const scope of ["dashboard", "processos"]) {
    const all = document.querySelector(`[data-bulk-all="${scope}"]`);
    if (!all) continue;
    const boxes = [...document.querySelectorAll(`.bulk-row-checkbox[data-bulk-checkbox="${scope}"]`)].filter(x => !x.disabled);
    all.disabled = boxes.length === 0;
    all.checked = boxes.length > 0 && boxes.every(x => selectedProcessIds.has(String(x.value)));
    all.indeterminate = boxes.some(x => selectedProcessIds.has(String(x.value))) && !all.checked;
  }
  const count = getEligibleSelectedProcessIds().length;
  for (const btn of [sendProcessBtn, document.getElementById("dashboardSendBtn")]) {
    if (btn) btn.textContent = count ? `Enviar ${count} ${count === 1 ? "processo" : "processos"}` : "Enviar processo";
  }
}

document.addEventListener("change", event => {
  const checkbox = event.target.closest?.(".bulk-row-checkbox");
  if (checkbox) {
    if (!checkbox.disabled) {
      if (checkbox.checked) selectedProcessIds.add(String(checkbox.value));
      else selectedProcessIds.delete(String(checkbox.value));
    }
    updateBatchSelectionControls();
    return;
  }
  const selectAll = event.target.closest?.(".bulk-select-all");
  if (selectAll) {
    const rows = document.querySelectorAll(`.bulk-row-checkbox[data-bulk-checkbox="${selectAll.dataset.bulkAll}"]`);
    rows.forEach(box => {
      if (box.disabled) return;
      if (selectAll.checked) selectedProcessIds.add(String(box.value));
      else selectedProcessIds.delete(String(box.value));
    });
    updateBatchSelectionControls();
  }
});

