function prepareSendMode() {
  selectedIdsForSending = getEligibleSelectedProcessIds();
  const bulk = selectedIdsForSending.length > 0;
  if (sendSingleField) sendSingleField.hidden = bulk;
  if (sendProcessSelect) {
    sendProcessSelect.disabled = bulk;
    sendProcessSelect.required = !bulk;
  }
  if (bulkSendSummary) {
    bulkSendSummary.hidden = !bulk;
    bulkSendSummary.textContent = bulk
      ? `${selectedIdsForSending.length} ${selectedIdsForSending.length === 1 ? "processo selecionado" : "processos selecionados"} para encaminhamento ao mesmo setor.`
      : "";
  }
}

/* Escuta antes do formulário tradicional: somente o envio em lote
   é tratado aqui. O envio individual mantém a rotina já aprovada. */
sendProcessForm?.addEventListener("submit", event => {
  if (selectedIdsForSending.length === 0) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  const data = new FormData(sendProcessForm);
  const destino = String(data.get("destino") || "").trim().toUpperCase();
  if (!destino) { showToast("Informe o setor de destino."); return; }
  const dataEnvio = String(data.get("dataEnvio") || isoDate(new Date()));
  const horaEnvio = String(data.get("horaEnvio") || new Date().toTimeString().slice(0, 5));
  const observacao = String(data.get("observacao") || "").trim();
  const meta = { destino, responsavel: "CEC", dataEnvio, horaEnvio, observacao };
  const ids = [...selectedIdsForSending];
  if (location.protocol === "file:") {
    showToast("Abra pelo iniciador local para encaminhar processos.");
    return;
  }
  let enviados = 0;
  let motivo = "";
  for (const id of ids) {
    const processo = processos.find(p => String(p.id) === id);
    if (!processo || !isProcessInCurrentSector(processo)) continue;
    const backup = JSON.parse(JSON.stringify(processo));
    try {
      ensureProcessRoutingData(processo);
      if (!processo.copiaDivacp) processo.copiaDivacp = buildDivacpCopy(processo);
      const setorAnterior = processo.setorAtual || "CEC";
      const envio = { id: createId("env"), origem: "CEC", setorAnterior,
        destino, dataEnvio, horaEnvio, responsavel: "CEC", observacao };
      processo.historicoEnvios.push(envio);
      processo.setorAtual = destino;
      if (!processo.syncId) processo.syncId = `CEC:${processo.id}`;
      recordProcessHistory(processo, "Envio de processo", `Processo enviado para ${destino}`,
        [`Setor anterior: ${setorAnterior}`, `Setor de destino: ${destino}`,
         observacao ? `Observação: ${observacao}` : ""].filter(Boolean).join("\n"),
         {data: dataEnvio, hora: horaEnvio, usuario: "CEC", refId: envio.id});
      const transfer = publishProcessTransfer(processo, "CEC", destino, meta);
      saveProcessos();
      // Transferência publicada no barramento compartilhado.
      selectedProcessIds.delete(id);
      enviados++;
    } catch(error) {
      Object.keys(processo).forEach(k => delete processo[k]);
      Object.assign(processo, backup);
      try { saveProcessos(); } catch {}
      motivo = error?.message || "erro no armazenamento";
      break;
    }
  }
  renderDashboard();
  renderProcessos();
  renderReports();
  updateBatchSelectionControls();
  if (enviados) {
    selectedIdsForSending = [];
    closeSendProcessModal();
  }
  showToast(motivo
    ? `${enviados} enviado(s); envio interrompido: ${motivo}.`
    : `${enviados} ${enviados === 1 ? "processo encaminhado" : "processos encaminhados"} para ${destino}.`);
}, true);


function warnHolidayOnOpeningDate(input) {
  if (!input) return true;
  const dateString = String(input.value || "").trim();
  if (!dateString) return true;

  const holidays = holidaysForDate(dateString).filter(item => item.type !== "optional");
  if (!holidays.length) return true;

  const uniqueNames = [...new Set(holidays.map(item => String(item.name || "Feriado").trim()).filter(Boolean))];
  const holidayLabel = uniqueNames.join(" / ") || "Feriado";
  const dateLabel = formatHolidayDate(dateString);
  const plural = uniqueNames.length > 1;
  const message = plural
    ? `A data ${dateLabel} possui os seguintes feriados: ${holidayLabel}.

Deseja continuar com esta Data de Abertura?`
    : `A data ${dateLabel} corresponde ao feriado ${holidayLabel}.

Deseja continuar com esta Data de Abertura?`;

  const confirmed = window.confirm(message);
  if (!confirmed) {
    input.value = "";
    input.focus();
    showToast("Data de Abertura removida. Selecione outra data.");
  }
  return confirmed;
}

