// Recuperação de confirmações feitas em versões anteriores: a confirmação já
// está registrada no barramento, mas a cópia sincronizada podia estar como pendente.
// Executar após SEADSync.init, para não deixar o registro compartilhado sobrescrever
// o recebimento confirmado no próximo F5.
function recoverConfirmedCecReceipts() {
  const acknowledged = new Map(
    loadTransferBus()
      .filter(t => t && t.id && t.recebidoEm
        && String(t.destino || "").toLocaleUpperCase("pt-BR") === "CEC"
        && (!t.recebidoPor || String(t.recebidoPor).toLocaleUpperCase("pt-BR") === "CEC"))
      .map(t => [t.id, t])
  );
  let corrected = 0;
  processos.forEach(p => {
    const transfer = acknowledged.get(p.transferenciaRecebimentoCecId);
    if (!transfer || p.recebidoCec) return;
    p.recebidoCec = true;
    p.dataRecebimentoCec = p.dataRecebimentoCec || transfer.recebidoEm;
    p.dataEntradaCec = p.dataEntradaCec || isoDate(new Date(transfer.recebidoEm));
    corrected++;
  });
  if (!corrected) return;
  saveProcessos();
  renderRecebimento();
  renderDashboard();
  renderProcessos();
  renderReports();
}
recoverConfirmedCecReceipts();

